/// What went wrong, as a sentence the user can act on.
#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum MobileError {
    /// The engine refused or failed: bad input, a missing file, a full disk.
    #[error("{0}")]
    Failed(String),
    /// [`init`] has not been called.
    #[error("the engine has not been started")]
    NotStarted,
    /// Something that runs one at a time - an export - is already running.
    #[error("{0}")]
    Busy(String),
}

impl From<String> for MobileError {
    fn from(message: String) -> Self {
        MobileError::Failed(message)
    }
}

/// What the whole process shares: where things live, the title painter and
/// the monitor's reader pool.
pub(crate) struct Context {
    /// The engine's own folders (models, title cache, logs).
    pub dirs: AppDirs,
    /// Where projects live: one folder each.
    pub projects: PathBuf,
    /// Scratch space the system may clear: exports in progress, stills.
    pub cache: PathBuf,
    /// Paints text clips into pictures for the compositor.
    pub titles: Titles,
    /// The monitor: decoded frames stay warm between scrubs.
    pub monitor: concat_host::preview::Monitor,
    /// The one export that may run at a time.
    pub exporter: concat_host::export::Exporter,
    /// Sound, once started.
    pub playback: Mutex<Option<std::sync::Arc<concat_host::playback::Playback>>>,
}

static CONTEXT: OnceLock<Context> = OnceLock::new();

/// The process's context, or [`MobileError::NotStarted`].
pub(crate) fn context() -> Result<&'static Context, MobileError> {
    CONTEXT.get().ok_or(MobileError::NotStarted)
}

/// Starts the engine for this process: `files_dir` is the app's private
/// files folder (projects and models live under it), `cache_dir` its cache
/// folder. Later calls do nothing.
#[uniffi::export]
pub fn init(files_dir: String, cache_dir: String) -> Result<(), MobileError> {
    if CONTEXT.get().is_some() {
        return Ok(());
    }
    let root = PathBuf::from(&files_dir);
    let dirs = AppDirs::under(&root.join("engine"));
    let projects = root.join("projects");
    let cache = PathBuf::from(&cache_dir);
    for folder in [&dirs.data, &projects, &cache] {
        std::fs::create_dir_all(folder)
            .map_err(|error| format!("could not create {}: {error}", folder.display()))?;
    }
    start_logging(&dirs);
    concat_host::logs::catch_panics();
    // Video decodes on the phone's chip wherever it can: its cores fell
    // behind playing a camera's files, and a stream the chip refuses, or a
    // reader past the few it has room for, decodes in software anyway.
    concat_media::set_hardware_decode(true);
    // Readers nobody has asked a frame of for ten seconds are closed, looked
    // at every five, as the desktop editor does: each holds buffers, one on
    // the chip holds one of its few decoders, and the playhead leaves files
    // behind. One reopens on its next frame.
    let _ = std::thread::Builder::new()
        .name("capcraft-readers".to_owned())
        .spawn(|| {
            loop {
                std::thread::sleep(std::time::Duration::from_secs(5));
                let closed = concat_host::scheduler()
                    .pool()
                    .close_idle(std::time::Duration::from_secs(10));
                if closed > 0 {
                    log::debug!("memory: closed {closed} idle decoder(s)");
                }
            }
        });
    // the looks imported before, beside the built-in filters
    looks::install(&dirs);
    let titles = Titles::new(&dirs);
    let _ = CONTEXT.set(Context {
        dirs,
        projects,
        cache,
        titles,
        monitor: concat_host::preview::Monitor::new(),
        exporter: concat_host::export::Exporter::new(),
        playback: Mutex::new(None),
    });
    log::info!(
        "CapCraft engine {} started in {files_dir}",
        env!("CARGO_PKG_VERSION")
    );
    Ok(())
}

/// The log goes to a file in the engine's folder and, on a phone, to logcat
/// under the tag `capcraft`.
fn start_logging(dirs: &AppDirs) {
    #[cfg(target_os = "android")]
    let extra: Option<Box<dyn log::Log>> = Some(Box::new(android_logger::AndroidLogger::new(
        android_logger::Config::default()
            .with_max_level(log::LevelFilter::Info)
            .with_tag("capcraft"),
    )));
    #[cfg(not(target_os = "android"))]
    let extra: Option<Box<dyn log::Log>> = None;
    if let Err(error) = concat_host::logs::open(dirs, extra) {
        eprintln!("capcraft: no log file: {error}");
    }
}

/// The engine's version, for the About screen.
#[uniffi::export]
pub fn engine_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

/// Gives back memory kept for later - decoded frames, readers - for when the
/// editor closes or the system asks the app to use less.
#[uniffi::export]
pub fn trim_memory() {
    if let Ok(context) = context() {
        context.monitor.clear();
    }
}

/// Where an export named `name` is written before the app publishes it:
/// the cache's `exports` folder, made if missing.
#[uniffi::export]
pub fn export_path(name: String) -> Result<String, MobileError> {
    let folder = context()?.cache.join("exports");
    std::fs::create_dir_all(&folder)
        .map_err(|error| format!("could not create {}: {error}", folder.display()))?;
    Ok(folder.join(name).to_string_lossy().into_owned())
}

/// The folder the engine keeps downloaded models in.
#[uniffi::export]
pub fn models_folder() -> Result<String, MobileError> {
    Ok(context()?.dirs.data.to_string_lossy().into_owned())
}

/// Seconds as whole microseconds, rounded.
pub(crate) fn micros(seconds: f64) -> i64 {
    if seconds.is_finite() {
        (seconds * 1_000_000.0).round() as i64
    } else {
        0
    }
}

/// Whole microseconds as seconds.
pub(crate) fn seconds(micros: i64) -> f64 {
    micros as f64 / 1_000_000.0
}

/// A picture: straight (not premultiplied) sRGB RGBA, 8 bits a channel, rows
/// top to bottom with no padding.
#[derive(Debug, Clone, uniffi::Record)]
pub struct Picture {
    /// Width in pixels.
    pub width: u32,
    /// Height in pixels.
    pub height: u32,
    /// `width * height * 4` bytes.
    pub rgba: Vec<u8>,
}

impl Picture {
    /// The engine's frame as eight-bit RGBA, whatever its depth.
    pub(crate) fn of(frame: concat_core::frame::Frame) -> Picture {
        let (width, height) = (frame.width(), frame.height());
        let rgba = if frame.bytes_per_pixel() == 4 {
            frame.into_pixels()
        } else {
            // Sixteen bits a channel, little-endian: the high byte of each.
            frame.pixels().chunks_exact(2).map(|pair| pair[1]).collect()
        };
        Picture {
            width,
            height,
            rgba,
        }
    }
}
